"""A tent captured through 16-bit RGB565 is still our camp.

The measured body colours (238,198,65)/(238,113,57)/(131,198,222) become
(232,196,64)/(232,112,56)/(128,196,216) when the core's RGB565 pixels are
expanded to 8 bits. The exact compare missed the tent on screen, so the
recall never started and the camp sat unattended (local g1190 2026-11-15,
production state resumed through the 1.61 core).
"""
from docich.hanjuku_speedrun.hanjuku.os_layer.pixels import Frame
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import CAMP_BAND, CAMP_ORANGE, CAMP_YELLOW, own_camps


def _quantized(colour):
    return (colour[0] & 0xF8, colour[1] & 0xFC, colour[2] & 0xF8)


def _tent_frame():
    width, height = 256, 224
    pixels = bytearray(width * height * 3)

    def put(x, y, colour):
        index = (y * width + x) * 3
        pixels[index:index + 3] = bytes(colour)

    for y in range(100, 108):
        for x in range(100, 110):
            colour = CAMP_YELLOW if x < 105 else CAMP_ORANGE
            put(x, y, _quantized(colour))
    for x in range(100, 110):
        put(x, 104, _quantized(CAMP_BAND))
    put(104, 97, (248, 0, 0))       # the fluttering flag, two adjacent pixels
    put(105, 97, (248, 0, 0))
    return Frame(width, height, bytes(pixels))


def test_a_565_quantized_tent_is_still_found():
    camps = own_camps(_tent_frame())
    assert len(camps) == 1
    assert camps[0]['clipped'] is False
    assert camps[0]['target'] == (96, 95)
